<template><view class="page personal-home"><view class="topbar"><view class="brand-mini"><text class="mini-leaf">♧</text><text>碳宝星球</text></view><text class="top-link">个人端</text></view><view class="profile-card card"><view class="profile-row"><view class="avatar">{{nickname.slice(0,1)}}</view><view class="profile-copy"><text class="welcome">{{nickname}}</text><text class="level">🌿 森林守护者</text></view><view class="score"><text>碳积分</text><strong>{{points}}</strong></view></view></view><view class="daily-card card"><view class="daily-head"><text class="daily-title">每日打卡</text><text class="daily-reward">今日最高 +17 积分</text></view><view class="daily-tasks"><view class="daily-task done"><text class="task-dot">✓</text><text>每日登录</text><text class="task-state">已完成</text></view><view class="daily-task" @tap="open('/pages/personal/daily-reading')"><text class="task-dot">📖</text><text>每日阅读</text><text class="task-state">去阅读</text></view><view class="daily-task" @tap="open('/pages/personal/daily-quiz')"><text class="task-dot">答</text><text>每日答题</text><text class="task-state">去答题</text></view></view></view><view class="section-title"><text>每日碳知识卡片</text><text class="muted">{{knowledge.category}}</text></view><view class="knowledge-card card"><text class="knowledge-title">{{knowledge.title}}</text><text class="knowledge-content">{{knowledge.content}}</text><text class="tag">{{knowledge.category}}</text></view><view class="ai-card" @tap="open('/pages/personal/ai')"><view class="ai-icon">✦</view><view class="ai-copy"><text class="ai-title">碳宝AI</text><text>可以咨询任何碳相关或生活问题。</text></view><view class="ai-btn">立即咨询</view></view><view class="section-title"><text>本周碳足迹</text><text class="muted">按每日获得积分统计</text></view><view class="chart card"><view v-for="(value,index) in chart" :key="index" class="chart-item"><text>{{value}}</text><view class="chart-bar" :style="{height:Math.max(value/2,8)+'rpx'}"/><text>{{days[index]}}</text></view></view><view class="tabbar"><view class="tab active" @tap="open('/pages/index/index')">⌂<text>首页</text></view><view class="tab" @tap="open('/pages/personal/challenges')">♧<text>低碳挑战</text></view><view class="tab" @tap="open('/pages/personal/activities')">◉<text>活动广场</text></view><view class="tab" @tap="open('/pages/personal/mall')">◇<text>商城</text></view><view class="tab" @tap="open('/pages/personal/profile')">●<text>个人中心</text></view></view></view></template>
<script>
import { callCloud } from '../../common/cloud.js'
export default {data(){return{nickname:'林间漫步者',points:0,knowledge:{title:'每日碳知识',content:'今天也一起做一个低碳选择。',category:'低碳生活'},chart:[0,0,0,0,0,0,0],days:['一','二','三','四','五','六','日']}},async onShow(){this.nickname=uni.getStorageSync('user_nickname')||'林间漫步者';this.points=Number(uni.getStorageSync('user_points')||0);const session=uni.getStorageSync('user_session')||{};try{const knowledge=await callCloud('carbon-knowledge-today');if(knowledge.data)this.knowledge=knowledge.data;const summary=await callCloud('point-daily-summary',{userId:session.id});if(summary.data)this.chart=summary.data.map(item=>Number(item.points||0))}catch(error){}},methods:{open(url){uni.navigateTo({url})}}}
</script>
<style lang="scss">@import '../../common/portal.scss';.personal-home{padding-top:22rpx;padding-bottom:150rpx}.topbar,.daily-head,.daily-task{display:flex;align-items:center}.topbar{justify-content:space-between;margin-bottom:22rpx}.brand-mini{color:#006d37;font-size:30rpx;font-weight:700}.mini-leaf{display:inline-flex;align-items:center;justify-content:center;width:48rpx;height:48rpx;margin-right:12rpx;border-radius:50%;background:#d6e6e3}.top-link,.muted{color:#6d7a6e;font-size:22rpx}.profile-card{padding:30rpx;background:#006d37;color:#fff}.profile-row{display:flex;align-items:center}.avatar{display:flex;align-items:center;justify-content:center;width:92rpx;height:92rpx;margin-right:18rpx;border-radius:50%;background:#d6e6e3;color:#006d37;font-size:32rpx}.profile-copy{flex:1}.welcome{display:block;font-size:34rpx;font-weight:700}.level{display:block;margin-top:8rpx;font-size:22rpx}.score{text-align:right}.score text,.score strong{display:block}.score strong{font-size:52rpx}.daily-card{margin-top:24rpx;padding:26rpx;background:linear-gradient(135deg,#effaf1,#d8efe0)}.daily-head{justify-content:space-between}.daily-title{font-size:31rpx;font-weight:700}.daily-reward,.task-state{color:#398052;font-size:22rpx}.daily-tasks{margin-top:18rpx}.daily-task{padding:14rpx 0;color:#53615f;font-size:23rpx}.task-dot{display:flex;align-items:center;justify-content:center;width:42rpx;height:42rpx;margin-right:14rpx;border-radius:50%;background:#fff;color:#398052}.task-state{margin-left:auto}.section-title{display:flex;justify-content:space-between;margin:30rpx 4rpx 14rpx;font-size:31rpx;font-weight:700}.knowledge-card{padding:28rpx}.knowledge-title{display:block;font-size:30rpx;font-weight:700}.knowledge-content{display:block;margin:14rpx 0;color:#66736b;font-size:24rpx;line-height:1.6}.tag{padding:8rpx 14rpx;border-radius:20rpx;background:#e5f4e9;color:#006d37;font-size:21rpx}.ai-card{display:flex;align-items:center;margin-top:24rpx;padding:28rpx;border-radius:26rpx;background:#d6e6e3}.ai-icon{margin-right:18rpx;font-size:38rpx}.ai-copy{flex:1}.ai-title{display:block;font-size:29rpx;font-weight:700}.ai-btn{padding:14rpx 18rpx;border-radius:24rpx;background:#006d37;color:#fff;font-size:21rpx}.chart{display:flex;align-items:flex-end;justify-content:space-around;height:260rpx;padding:24rpx}.chart-item{display:flex;flex-direction:column;align-items:center;justify-content:flex-end;height:100%;color:#6d7a6e;font-size:19rpx}.chart-bar{width:24rpx;margin:8rpx 0;border-radius:20rpx;background:#27ae60}.tabbar{position:fixed;left:0;right:0;bottom:0;z-index:30;display:flex;justify-content:space-around;padding:12rpx;background:rgba(247,250,249,.96);box-shadow:0 -8rpx 24rpx #0000000f}.tab{display:flex;flex-direction:column;align-items:center;min-width:88rpx;color:#53615f;font-size:19rpx}.tab.active{color:#00391a;background:#d6e6e3;border-radius:22rpx}</style>
